19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "toDisplayName")
24	    @Mapping(target = "salutation", source = "owner", qualifiedByName = "toSalutation")
25	    @Mapping(target = "telephoneDisplay", source = "owner", qualifiedByName = "toTelephoneDisplay")
26	    @Mapping(target = "initials", source = "owner", qualifiedByName = "toInitials")
27	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "toMembershipNumber")
28	    @Mapping(target = "fiscalYear", source = "owner", qualifiedByName = "toFiscalYear")
29	    @Mapping(target = "checkDigit", source = "owner", qualifiedByName = "toCheckDigit")
30	    @Mapping(target = "membershipPoints", source = "owner", qualifiedByName = "toMembershipPoints")
31	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "toMembershipLevel")
32	    @Mapping(target = "locality", source = "owner", qualifiedByName = "toLocality")
33	    @Mapping(target = "timezone", source = "owner", qualifiedByName = "toTimezone")
34	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "toContactPreference")
35	    @Mapping(target = "identityKey", source = "owner", qualifiedByName = "toIdentityKey")
36	    @Mapping(target = "ageBand", source = "owner", qualifiedByName = "toAgeBand")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    /**
40	     * Derives the owner's {@code ageBand} from its {@code birthDate}, computed against the
41	     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18 on the registration date,
42	     * {@code 'ADULT'} from 18 up to and including 64, and {@code 'SENIOR'} at 65 or over. Returns
43	     * {@code null} when either the birth date or the registration date is absent.
44	     */
45	    @Named("toAgeBand")
46	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
47	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
48	            return null;
49	        }
50	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
51	        if (age < 18) {
52	            return OwnerDto.AgeBandEnum.MINOR;
53	        }
54	        if (age < 65) {
55	            return OwnerDto.AgeBandEnum.ADULT;
56	        }
57	        return OwnerDto.AgeBandEnum.SENIOR;
58	    }
59	
60	    /**
61	     * Derives the owner's duplicate-detection {@code identityKey}: the single key that consolidates
62	     * the former separate telephone, email and household checks. It is the owner's normalized
63	     * telephone, its email (lower-cased and trimmed, or the empty string when absent) and its
64	     * household identifier (or the empty string when absent), joined in that order by {@code '|'}.
65	     * Because the telephone is part of the key, two members of the same household with different
66	     * telephones have different identity keys; only an exact full-key match is a duplicate.
67	     */
68	    @Named("toIdentityKey")
69	    default String toIdentityKey(Owner owner) {
70	        if (owner == null) {
71	            return null;
72	        }
73	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().trim();
74	        String email = owner.getEmail() == null ? "" : owner.getEmail().trim().toLowerCase(java.util.Locale.ROOT);
75	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
76	        return telephone + "|" + email + "|" + householdId;
77	    }
78	
79	    /**
80	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when the owner has a non-blank
81	     * email, otherwise {@code 'PHONE'}.
82	     */
83	    @Named("toContactPreference")
84	    default String toContactPreference(Owner owner) {
85	        if (owner == null) {
86	            return null;
87	        }
88	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
89	        return hasEmail ? "EMAIL" : "PHONE";
90	    }
91	
92	    /**
93	     * Fixed city-to-region table used as the fallback for deriving an owner's locality.
94	     */
95	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
96	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
97	
98	    /**
99	     * Fixed region-to-timezone table mapping each canonical region to its IANA timezone name
100	     * ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}).
101	     */
102	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
103	        "NSW", "Australia/Sydney",
104	        "VIC", "Australia/Melbourne",
105	        "QLD", "Australia/Brisbane");
106	
107	    /**
108	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
109	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Used to derive an
110	     * owner's locality from its postcode in preference to its city.
111	     */
112	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
113	        "NSW", new int[] {2000, 2099},
114	        "VIC", new int[] {3000, 3099},
115	        "QLD", new int[] {4000, 4099});
116	
117	    /**
118	     * Derives the owner's canonical region, the {@code REGION} component of its {@code customerCode}.
119	     * The postcode takes precedence: when the owner has a well-formed 4-digit postcode that falls
120	     * within a known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
121	     * 4000-4099}), that region is returned. Otherwise the region is looked up from the fixed
122	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}),
123	     * yielding {@code 'UNKNOWN'} when the city is not in the table. Preferring the postcode returns
124	     * the same region for known cities but disambiguates cities that share a name.
125	     */
126	    default String toRegion(Owner owner) {
127	        if (owner == null) {
128	            return null;
129	        }
130	        String regionByPostcode = regionForPostcode(owner.getPostcode());
131	        if (regionByPostcode != null) {
132	            return regionByPostcode;
133	        }
134	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
135	    }
136	
137	    /**
138	     * Derives the owner's locality as the {@code REGION} component of its region-and-hash
139	     * {@code customerCode} (the prefix before the first {@code '-'}). The locality therefore shares
140	     * the customer code's identity rather than being computed independently. When the customer code
141	     * is absent the region is derived directly from the owner's postcode and city via
142	     * {@link #toRegion(Owner)}.
143	     */
144	    @Named("toLocality")
145	    default String toLocality(Owner owner) {
146	        if (owner == null) {
147	            return null;
148	        }
149	        String customerCode = owner.getCustomerCode();
150	        if (customerCode != null) {
151	            int dash = customerCode.indexOf('-');
152	            if (dash >= 0) {
153	                return customerCode.substring(0, dash);
154	            }
155	        }
156	        return toRegion(owner);
157	    }
158	
159	    /**
160	     * Derives the owner's {@code timezone} as the IANA timezone name mapped from its locality/region
161	     * via the fixed region-to-timezone table ({@code NSW->Australia/Sydney},
162	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}). Returns {@code null} when the
163	     * owner's region is not one of the tabled regions.
164	     */
165	    @Named("toTimezone")
166	    default String toTimezone(Owner owner) {
167	        if (owner == null) {
168	            return null;
169	        }
170	        return REGION_TIMEZONE.get(toLocality(owner));
171	    }
172	
173	    /**
174	     * Returns the region whose inclusive postcode range contains the given 4-digit postcode, or
175	     * {@code null} when the postcode is absent, malformed, or in no known range.
176	     */
177	    private static String regionForPostcode(String postcode) {
178	        if (postcode == null || !postcode.matches("\\d{4}")) {
179	            return null;
180	        }
181	        int value = Integer.parseInt(postcode);
182	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
183	            int[] range = entry.getValue();
184	            if (value >= range[0] && value <= range[1]) {
185	                return entry.getKey();
186	            }
187	        }
188	        return null;
189	    }
190	
191	    /**
192	     * Formats the owner's stored names as {@code 'LastName, FirstName'}.
193	     */
194	    @Named("toDisplayName")
195	    default String toDisplayName(Owner owner) {
196	        if (owner == null) {
197	            return null;
198	        }
199	        return owner.getLastName() + ", " + owner.getFirstName();
200	    }
201	
202	    /**
203	     * Composes the owner's {@code salutation}: the owner's {@code title} and {@code lastName} joined
204	     * by a single space when a title is present, or just the {@code lastName} when no title is
205	     * supplied (absent or blank).
206	     */
207	    @Named("toSalutation")
208	    default String toSalutation(Owner owner) {
209	        if (owner == null) {
210	            return null;
211	        }
212	        String title = owner.getTitle();
213	        if (title == null || title.isBlank()) {
214	            return owner.getLastName();
215	        }
216	        return title + " " + owner.getLastName();
217	    }
218	
219	    /**
220	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
221	     * the national digits grouped in threes, e.g. {@code "+61412345678"} becomes
222	     * {@code "+61 412 345 678"}. The country code is a single {@code '1'} for NANP ({@code +1}) numbers
223	     * and two digits otherwise (covering the {@code +61} numbers the app stores). Returns the value
224	     * unchanged when it is absent or not a well-formed E.164 number, leaving raw {@code telephone}
225	     * untouched.
226	     */
227	    @Named("toTelephoneDisplay")
228	    default String toTelephoneDisplay(Owner owner) {
229	        if (owner == null) {
230	            return null;
231	        }
232	        String telephone = owner.getTelephone();
233	        if (telephone == null || !telephone.matches("\\+[0-9]{8,15}")) {
234	            return telephone;
235	        }
236	        String digits = telephone.substring(1);
237	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
238	        String countryCode = digits.substring(0, countryCodeLength);
239	        String national = digits.substring(countryCodeLength);
240	        StringBuilder sb = new StringBuilder("+").append(countryCode);
241	        for (int i = 0; i < national.length(); i++) {
242	            if (i % 3 == 0) {
243	                sb.append(' ');
244	            }
245	            sb.append(national.charAt(i));
246	        }
247	        return sb.toString();
248	    }
249	
250	    /**
251	     * Returns the owner's initials as the upper-cased first letters of firstName and lastName,
252	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
253	     */
254	    @Named("toInitials")
255	    default String toInitials(Owner owner) {
256	        if (owner == null) {
257	            return null;
258	        }
259	        return initial(owner.getFirstName()) + initial(owner.getLastName());
260	    }
261	
262	    /**
263	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}, where {@code YY} is
264	     * the last two digits of the fiscal year of the {@code registrationDate}, e.g.
265	     * {@code 'NSW-1A2B3C4D-M26'}. The fiscal year starts on 1 July and is identified by the calendar
266	     * year in which it ends. Returns {@code null} when either the customer code or the registration
267	     * date is absent.
268	     */
269	    @Named("toMembershipNumber")
270	    default String toMembershipNumber(Owner owner) {
271	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
272	            return null;
273	        }
274	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYear(owner.getRegistrationDate()) % 100);
275	    }
276	
277	    /**
278	     * Derives the owner's {@code fiscalYear} from its {@code registrationDate}, formatted
279	     * {@code 'FY<YY>'} where {@code YY} is the last two digits of the fiscal year, e.g. {@code 'FY26'}.
280	     * The fiscal year starts on 1 July and is identified by the calendar year in which it ends: a date
281	     * from 1 July onwards belongs to the fiscal year ending in the following calendar year, and a date
282	     * before 1 July to the fiscal year ending in the same calendar year. Returns {@code null} when the
283	     * registration date is absent.
284	     */
285	    @Named("toFiscalYear")
286	    default String toFiscalYear(Owner owner) {
287	        if (owner == null || owner.getRegistrationDate() == null) {
288	            return null;
289	        }
290	        return String.format("FY%02d", fiscalYear(owner.getRegistrationDate()) % 100);
291	    }
292	
293	    /**
294	     * Returns the fiscal year of the given date as the calendar year in which the fiscal year ends.
295	     * The fiscal year starts on 1 July, so a date in July or later belongs to the fiscal year ending
296	     * in the next calendar year ({@code year + 1}); an earlier date belongs to the fiscal year ending
297	     * in its own calendar year.
298	     *
299	     * @param date the date whose fiscal year is computed, never {@code null}
300	     * @return the calendar year in which the date's fiscal year ends
301	     */
302	    static int fiscalYear(LocalDate date) {
303	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
304	    }
305	
306	    /**
307	     * Returns the owner's membership points, assigned on creation: starts at {@code 0}, plus {@code 2}
308	     * when a non-blank email is present, plus {@code 1} when the owner has no namesakes
309	     * ({@code namesakeCount} is 0), plus {@code 2} for a household of {@code 3} or more members, plus
310	     * {@code 3} for a tenure of one or more elapsed fiscal years since the {@code registrationDate}.
311	     * This qualified mapping cannot observe the owner's household size (which requires counting other
312	     * owners), so it computes the points as if the owner were the only member of its household; the
313	     * controller recomputes the points with the real household size via
314	     * {@link #membershipPointsFor(Owner, int)} before returning the owner.
315	     */
316	    @Named("toMembershipPoints")
317	    default Integer toMembershipPoints(Owner owner) {
318	        if (owner == null) {
319	            return null;
320	        }
321	        return membershipPointsFor(owner, 1);
322	    }
323	
324	    /**
325	     * Returns the owner's numeric membership level, derived from its membership points: level
326	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
327	     * {@code 4} for {@code 6} or more. As with {@link #toMembershipPoints(Owner)}, the household size
328	     * is not observable here and is treated as a single member.
329	     */
330	    @Named("toMembershipLevel")
331	    default Integer toMembershipLevel(Owner owner) {
332	        if (owner == null) {
333	            return null;
334	        }
335	        return membershipLevelFor(membershipPointsFor(owner, 1));
336	    }
337	
338	    /**
339	     * Computes an owner's membership points from the given household size: starts at {@code 0}, plus
340	     * {@code 2} when a non-blank email is present, plus {@code 1} when the owner has no namesakes
341	     * ({@code namesakeCount} is 0), plus {@code 2} when {@code householdSize} is {@code 3} or more,
342	     * plus {@code 3} for a tenure of one or more elapsed fiscal years (each starting 1 July) between
343	     * the {@code registrationDate} and today.
344	     *
345	     * @param owner the owner whose points are computed, never {@code null}
346	     * @param householdSize the number of owners sharing the owner's household
347	     * @return the owner's membership points
348	     */
349	    static int membershipPointsFor(Owner owner, int householdSize) {
350	        int points = 0;
351	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
352	        if (hasEmail) {
353	            points += 2;
354	        }
355	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
356	        if (noNamesakes) {
357	            points += 1;
358	        }
359	        if (householdSize >= 3) {
360	            points += 2;
361	        }
362	        boolean tenured = owner.getRegistrationDate() != null
363	            && fiscalYear(LocalDate.now()) - fiscalYear(owner.getRegistrationDate()) >= 1;
364	        if (tenured) {
365	            points += 3;
366	        }
367	        return points;
368	    }
369	
370	    /**
371	     * Maps membership points to the numeric membership level: level {@code 1} for {@code 0-1} points,
372	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
373	     *
374	     * @param points the owner's membership points
375	     * @return the corresponding membership level (1-4)
376	     */
377	    static int membershipLevelFor(int points) {
378	        if (points <= 1) {
379	            return 1;
380	        }
381	        if (points <= 3) {
382	            return 2;
383	        }
384	        if (points <= 5) {
385	            return 3;
386	        }
387	        return 4;
388	    }
389	
390	    /**
391	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
392	     * contained in the owner's {@code customerCode}. Returns {@code null} when the customer code is
393	     * absent.
394	     */
395	    @Named("toCheckDigit")
396	    default Integer toCheckDigit(Owner owner) {
397	        if (owner == null || owner.getCustomerCode() == null) {
398	            return null;
399	        }
400	        int sum = 0;
401	        boolean dbl = true;
402	        String code = owner.getCustomerCode();
403	        for (int i = code.length() - 1; i >= 0; i--) {
404	            char c = code.charAt(i);
405	            if (c < '0' || c > '9') {
406	                continue;
407	            }
408	            int d = c - '0';
409	            if (dbl) {
410	                d *= 2;
411	                if (d > 9) {
412	                    d -= 9;
413	                }
414	            }
415	            sum += d;
416	            dbl = !dbl;
417	        }
418	        return (10 - (sum % 10)) % 10;
419	    }
420	
421	    private static String initial(String name) {
422	        if (name == null || name.isEmpty()) {
423	            return "";
424	        }
425	        return Character.toUpperCase(name.charAt(0)) + ".";
426	    }
427	
428	    Owner toOwner(OwnerDto ownerDto);
429	
430	    @Mapping(target = "id", ignore = true)
431	    @Mapping(target = "pets", ignore = true)
432	    Owner toOwner(OwnerFieldsDto ownerDto);
433	
434	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
435	
436	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
437	
438	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
439	        OwnerPageDto ownerPageDto = new OwnerPageDto();
440	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
441	        ownerPageDto.setPage(ownerPage.getNumber());
442	        ownerPageDto.setSize(ownerPage.getSize());
443	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
444	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
445	        return ownerPageDto;
446	    }
447	}
